'use strict';
var JSZip = require('jszip');

// Minutas embebidas como base64
var MINUTAS = {
  'acabadosvis': '',
  'visualizza': '',
  'gran_central_sin_bono': '',
  'gran_central_con_bono': ''
};

function getMinuta(tipo) {
  var b64 = MINUTAS[tipo];
  if (!b64) return null;
  return Buffer.from(b64, 'base64');
}

function fmtPesos(n) {
  return '$' + Number(n).toLocaleString('es-CO');
}

function numLetras(n) {
  n = Math.round(Number(n));
  if (!n) return 'CERO';
  var u = ['','UN','DOS','TRES','CUATRO','CINCO','SEIS','SIETE','OCHO','NUEVE',
            'DIEZ','ONCE','DOCE','TRECE','CATORCE','QUINCE','DIECISEIS',
            'DIECISIETE','DIECIOCHO','DIECINUEVE'];
  var d = ['','DIEZ','VEINTE','TREINTA','CUARENTA','CINCUENTA',
            'SESENTA','SETENTA','OCHENTA','NOVENTA'];
  var c = ['','CIENTO','DOSCIENTOS','TRESCIENTOS','CUATROCIENTOS','QUINIENTOS',
            'SEISCIENTOS','SETECIENTOS','OCHOCIENTOS','NOVECIENTOS'];
  function m1000(x) {
    if (x === 0)   return '';
    if (x < 20)    return u[x];
    if (x < 100) { var a=Math.floor(x/10),b=x%10; return d[a]+(b?' Y '+u[b]:''); }
    if (x === 100) return 'CIEN';
    var a=Math.floor(x/100),b=x%100;
    return c[a]+(b?' '+m1000(b):'');
  }
  var mil=Math.floor(n/1000000), miles=Math.floor((n%1000000)/1000), uni=n%1000;
  var r='';
  if (mil)   r+=(mil===1?'UN MILLON':m1000(mil)+' MILLONES')+' ';
  if (miles) r+=(miles===1?'MIL':m1000(miles)+' MIL')+' ';
  if (uni)   r+=m1000(uni)+' ';
  return r.trim()+' PESOS M/CTE';
}

function pctTxt(p) {
  p = Math.round(Number(p));
  var u = ['','UN','DOS','TRES','CUATRO','CINCO','SEIS','SIETE','OCHO','NUEVE',
            'DIEZ','ONCE','DOCE','TRECE','CATORCE','QUINCE','DIECISEIS',
            'DIECISIETE','DIECIOCHO','DIECINUEVE'];
  var d = ['','DIEZ','VEINTE','TREINTA','CUARENTA','CINCUENTA',
            'SESENTA','SETENTA','OCHENTA','NOVENTA'];
  if (p <= 0) return 'CERO';
  if (p < 20)  return u[p];
  var a=Math.floor(p/10), b=p%10;
  return d[a]+(b?' Y '+u[b]:'');
}

function escapeXml(str) {
  return String(str).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;');
}
function extractParaText(paraXml) {
  var matches = paraXml.match(/<w:t[^>]*>([^<]*)<\/w:t>/g) || [];
  return matches.map(function(m){ return m.replace(/<[^>]*>/g,''); }).join('');
}
function applyReplacements(text, sortedReps) {
  var result = text;
  for (var i=0; i<sortedReps.length; i++) {
    var k=sortedReps[i][0], v=sortedReps[i][1];
    if (result.indexOf(k) !== -1) result = result.split(k).join(String(v));
  }
  return result;
}
function replaceParagraphText(paraXml, sortedReps) {
  var original = extractParaText(paraXml);
  var updated  = applyReplacements(original, sortedReps);
  if (updated === original) return paraXml;
  var firstDone = false;
  return paraXml.replace(/<w:t([^>]*)>[^<]*<\/w:t>/g, function(match, attrs) {
    if (!firstDone) { firstDone = true; return '<w:t xml:space="preserve">'+escapeXml(updated)+'</w:t>'; }
    return '<w:t></w:t>';
  });
}
async function replaceInDocx(docxBuffer, replacements) {
  var zip = await JSZip.loadAsync(docxBuffer);
  var xmlFile = zip.file('word/document.xml');
  if (!xmlFile) throw new Error('word/document.xml no encontrado');
  var xml = await xmlFile.async('string');
  var sorted = Object.entries(replacements).sort(function(a,b){ return b[0].length-a[0].length; });
  xml = xml.replace(/<w:p[ >][\s\S]*?<\/w:p>/g, function(para){ return replaceParagraphText(para, sorted); });
  zip.file('word/document.xml', xml);
  return zip.generateAsync({ type:'nodebuffer', mimeType:'application/vnd.openxmlformats-officedocument.wordprocessingml.document' });
}

module.exports = async (req, res) => {
  res.setHeader('Access-Control-Allow-Origin', '*');
  res.setHeader('Access-Control-Allow-Headers', 'Content-Type');
  res.setHeader('Access-Control-Allow-Methods', 'POST, OPTIONS');
  res.setHeader('X-VIS-CO-Version', 'v9');
  if (req.method === 'OPTIONS') return res.status(200).end();
  if (req.method !== 'POST')   return res.status(405).end('Method not allowed');

  try {
    var datos = typeof req.body === 'string' ? JSON.parse(req.body) : req.body;
    var tipo       = datos.tipo       || '';
    var nombre     = datos.nombre     || '';
    var cedula     = datos.cedula     || '';
    var lugar_exp  = datos.lugar_exp  || '';
    var direccion  = datos.direccion  || '';
    var correo     = datos.correo     || '';
    var celular    = datos.celular    || '';
    var cotizacion = datos.cotizacion || '';
    var valor_total = datos.valor_total;
    var congelacion = datos.congelacion;
    var fecha_cong = datos.fecha_cong || '';
    var dia        = datos.dia        || '';
    var mes        = datos.mes        || '';
    var torre      = datos.torre      || '';
    var apto       = datos.apto       || '';
    var proyecto   = datos.proyecto   || '';

    if (!tipo || !nombre || !valor_total) {
      return res.status(400).json({ error: 'Faltan campos: tipo, nombre, valor_total' });
    }

    var docxBuffer = getMinuta(tipo);
    if (!docxBuffer) return res.status(400).json({ error: 'Tipo desconocido: '+tipo });

    var vt   = Number(valor_total);
    var cong = Number(congelacion) || 5000000;

    var cotizNum = cotizacion
      .replace(/^[Cc][Oo][-\s]*/,'')
      .replace(/[-\s]*20\d\d$/,'')
      .replace(/-/g,'')
      .trim();

    var conNum   = 'CON-'+cotizNum+'-2026';
    var cotizFmt = 'CO - '+cotizNum;
    var reps = {};

    if (tipo === 'acabadosvis') {
      if (!fecha_cong) return res.status(400).json({ error: 'Falta la fecha de vigencia.' });
      var resto=vt-cong, p2=Math.round(resto*0.50), p3=Math.round(resto*0.20);
      var p4=Math.round(resto*0.20), p5=vt-cong-p2-p3-p4;
      var pctCong=Math.round((cong/vt)*100), pct2=Math.round((p2/vt)*100);
      reps = {
        'No. CON - XXXXX'                                                          : 'No. CON - '+cotizNum,
        'XXXXXXXXXXXXXXXXXXXX mayor de edad'                                        : nombre+' mayor de edad',
        'ciudadania No. XXXXXXXXXXXXX expedida'                                    : 'ciudadania No. '+cedula+' expedida',
        'expedida en XXXXXXXXXX,'                                                  : 'expedida en '+lugar_exp+',',
        'ubicado en XXXXXXXXXXXXXXXXXXXX Torre'                                    : 'ubicado en '+proyecto+' Torre',
        'Torre XX Apartamento XXXX'                                                : 'Torre '+torre+' Apartamento '+apto,
        'CO - XXXXXXX'                                                             : cotizFmt,
        'XXXXXXXXXXXXXXXXXXXXXXXXXXXXXXXXX PESOS M/CTE ($XX.XXX.XXX)'             : numLetras(vt)+' ('+fmtPesos(vt)+')',
        'XXXXXXXX por ciento XX%'                                                  : pctTxt(pct2)+' por ciento',
        'XXXXXX por ciento XX%'                                                    : pctTxt(pctCong)+' por ciento',
        'XXXXXXXXXXXXXXXXXXXXXXXXXXXXXXX PESOS M/CTE ($XX.XXX.XXX)'               : numLetras(p2)+' ('+fmtPesos(p2)+')',
        'XXXXXXXXXXXXXXXXXXXXXXXXXXXXXXXXXXXXXXXXXXXXXXXXXXXXXXXXXXX PESOS MCTE ($X.XXX.XXX)': numLetras(p3)+' ('+fmtPesos(p3)+')',
        'XXXXXXXXXXXXXXXXXXXXXXXXXXXXXXXXXXXXXXXXXXXXXXXXXXXXXXXXXXXXXX PESOS MCTE ($X.XXX.XXX)': numLetras(p4)+' ('+fmtPesos(p4)+')',
        'XXXXXXXXXXXXXXXXXXXXXXXXXXXXXXXXXXXXXXXXXXXXXXXXXXXXXXXXXXXXX PESOS MCTE ($X.XXX.XXX)': numLetras(p5)+' ('+fmtPesos(p5)+')',
        'hasta el XXXXXXXXX y'                                                     : 'hasta el '+fecha_cong+' y',
        'el dia XX dia del mes de xxxxx'                                           : 'el ('+dia+') dia del mes de '+mes,
        'Nombre: XXXXXXXXXXXXXXXXX'                                                : 'Nombre: '+nombre,
        'Email: XXXXXXXXXXXXXXXXXXXXX'                                             : 'Email: '+correo,
        'Email: XXXXXXXXXXXXXXXXXXXX'                                              : 'Email: '+correo,
        'Teléfono: 3XXXXXXXXXXXXX'                                                 : 'Teléfono: '+celular,
        'Lugar: XXXXXXXXXX'                                                        : 'Lugar: '+lugar_exp,
        'Dirección: xxxxxxxxxxxxxx'                                                : 'Dirección: '+direccion
      };

    } else if (tipo === 'visualizza') {
      if (!fecha_cong) return res.status(400).json({ error: 'Falta la fecha de vigencia.' });
      var congViz=5000000, resto=vt-congViz;
      var p2=Math.round(resto*0.50), p3=Math.round(resto*0.20);
      var p4=Math.round(resto*0.20), p5=vt-congViz-p2-p3-p4;
      var pctCong=Math.round((congViz/vt)*100), pct2=Math.round((p2/vt)*100);
      reps = {
        'CON-XXXXX-26'                                                                       : conNum,
        'XXXXXXXXXXXXXXXXXXX'                                                                : nombre,
        'XXXXXXXXXXX'                                                                        : cedula,
        'expedida en XXXXXXXXXX,'                                                            : 'expedida en '+lugar_exp+',',
        'XXXXXXXXXXXXXXXXXXXXXXX'                                                            : proyecto+' Torre '+torre+' Apartamento '+apto,
        'CO-XXXXXX-25'                                                                       : 'CO-'+cotizNum+'-2026',
        'CO-XXXXX-25'                                                                        : 'CO-'+cotizNum+'-2026',
        'CO-XXXXXXXX'                                                                        : 'CO-'+cotizNum+'-2026',
        'XXXXXXXXXXXXXXXXXXXXXXXXXXXXX PESOS M/CTE ($XX.XXX.XXX)'                           : numLetras(vt)+' ('+fmtPesos(vt)+')',
        'XXXXXX por ciento XX%'                                                              : pctTxt(pctCong)+' por ciento '+pctCong+'%',
        'XXXXXXXX por ciento XX%'                                                            : pctTxt(pct2)+' por ciento '+pct2+'%',
        'XXXXXXXXXXXXXXXXXXXXXXXXXXXXXXX PESOS M/CTE ($XX.XXX.XXX)'                         : numLetras(p2)+' ('+fmtPesos(p2)+')',
        'XXXXXXXXXXXXXXXXXXXXXXXXXXXXXXXXXXXXXXXXXXXXXXXXXXXXXXXXXXX PESOS MCTE ($X.XXX.XXX)': numLetras(p3)+' ('+fmtPesos(p3)+')',
        'XXXXXXXXXXXXXXXXXXXXXXXXXXXXXXXXXXXXXXXXXXXXXXXXXXXXXXXXXXXXXX PESOS MCTE ($X.XXX.XXX)': numLetras(p4)+' ('+fmtPesos(p4)+')',
        'XXXXXXXXXXXXXXXXXXXXXXXXXXXXXXXXXXXXXXXXXXXXXXXXXXXXXXXXXXXXX PESOS MCTE ($X.XXX.XXX)': numLetras(p5)+' ('+fmtPesos(p5)+')',
        'MES DE XXXXXX DE 202X Y UN MES MAS'                                                : fecha_cong.toUpperCase()+' Y UN MES MAS',
        'Nombre: XXXXXXXXXXXXXXXXXXXX'                                                       : 'Nombre: '+nombre,
        'Email: XXXXXXXXXXXXXXXXXXXXX'                                                       : 'Email: '+correo,
        'Email: XXXXXXXXXXXXXXX'                                                             : 'Email: '+correo,
        'Teléfono: XXXXXXXXXX'                                                               : 'Teléfono: '+celular,
        'Lugar: XXXXXXX'                                                                     : 'Lugar: '+lugar_exp,
        'Dirección: XXXXXXXXXXXXXXXX'                                                        : 'Dirección: '+direccion,
        '(23) día del mes de julio'                                                          : '('+dia+') día del mes de '+mes
      };

    } else if (tipo === 'gran_central_sin_bono') {
      if (!fecha_cong) return res.status(400).json({ error: 'Falta la fecha de vigencia.' });
      var resto=vt-cong, p2=Math.round(resto*0.50), p3=Math.round(resto*0.20);
      var p4=Math.round(resto*0.20), p5=vt-cong-p2-p3-p4;
      var pctCong=Math.round((cong/vt)*100), pct2=Math.round((p2/vt)*100);
      var pct3=Math.round((p3/vt)*100), pct4=Math.round((p4/vt)*100), pct5=Math.round((p5/vt)*100);
      reps = {
        'CON-xxxxxxxx'                                                                       : conNum,
        'XXXXXXXXXXXXXXXXXXXXXXXXX'                                                          : nombre,
        'XXXXXXXXXXXXXXXX'                                                                   : cedula,
        'expedida en XXXXXXXXX,'                                                             : 'expedida en '+lugar_exp+',',
        'Apartamento XXXX'                                                                   : 'Apartamento '+apto,
        'CO-XXXX-2026'                                                                       : 'CO-'+cotizNum+'-2026',
        'XXXXXXXXXXXXXXXXXXXXXXXXXXXXXXXXXXXXXXXXXXXXXXXX M/CTE ($XX.XXX.XXX)'               : numLetras(vt)+' ('+fmtPesos(vt)+')',
        'XXXXXXX por ciento XX%'                                                             : pctTxt(pctCong)+' por ciento '+pctCong+'%',
        'XXXXXXXXXXXXXXXXXXXXXXXXXXXXXXXXXX M/CTE ($X.XXX.XXX)'                             : numLetras(cong)+' ('+fmtPesos(cong)+')',
        'XXXXXXXXX por ciento XX%'                                                           : pctTxt(pct2)+' por ciento '+pct2+'%',
        'XXXXXXXXXXXXXXXXXXXXXXXXXXXXXXXXXXXXXXXXXXXXXXXX PESOS ($XX.XXX.XXXX)'              : numLetras(p2)+' ('+fmtPesos(p2)+')',
        'Tercer pago equivale al XXXXXX por ciento XX%'                                      : 'Tercer pago equivale al '+pctTxt(pct3)+' por ciento '+pct3+'%',
        'XXXXXXXXXXXXXXXXXXXXXXXXXXXXXXXXXXXXXXXXXXXXX PESOS ($X,XXX,XXX)'                   : numLetras(p3)+' ('+fmtPesos(p3)+')',
        'Cuarto pago equivale XXXXXXX por ciento XX%'                                        : 'Cuarto pago equivale '+pctTxt(pct4)+' por ciento '+pct4+'%',
        'XXXXXXXXXXXXXXXXXXXXXXXXXXXXXXXXXXXXXXXXXXXXPESOS ($X,XXX,XXX)'                     : numLetras(p4)+' ('+fmtPesos(p4)+')',
        'Quinto pago equivale al XXXXXX por ciento XX%'                                      : 'Quinto pago equivale al '+pctTxt(pct5)+' por ciento '+pct5+'%',
        'XXXXXXXXXXXXXXXXXXXXXXXXXXXXXXXXXXXXXXXXX PESOS ($X,XXX,XXX)'                       : numLetras(p5)+' ('+fmtPesos(p5)+')',
        'Nombre: xxxxxxxxxxx'                                                                : 'Nombre: '+nombre,
        'Email: xxxxxxxxxxxxxx'                                                              : 'Email: '+correo,
        'Email: xxxxxxxxxxx'                                                                 : 'Email: '+correo,
        'Teléfono: xxxxxxx'                                                                  : 'Teléfono: '+celular,
        'Lugar: xxxxxxx'                                                                     : 'Lugar: '+lugar_exp,
        'Dirección: xxxxxxxx'                                                                : 'Dirección: '+direccion,
        'xx día del mes de xxxx'                                                             : dia+' día del mes de '+mes
      };

    } else if (tipo === 'gran_central_con_bono') {
      var BONO = 40247135;
      var valorNeto = vt - BONO;
      reps = {
        'CON-xxxxxxxx'                                                                       : conNum,
        'XXXXXXXXXXXXXXXXXXXXXXXXX'                                                          : nombre,
        'XXXXXXXXXXXXXXXX'                                                                   : cedula,
        'expedida en XXXXXXXXX,'                                                             : 'expedida en '+lugar_exp+',',
        'Apartamento XXXX'                                                                   : 'Apartamento '+apto,
        'CO-XXXX-2026'                                                                       : 'CO-'+cotizNum+'-2026',
        'XXXXXXXXXXXXXXXXXXXXXXXXXXXXXXXXXXXXXXXXXXXX PESOS M/CTE ($XX.XXX.XXX)'             : numLetras(valorNeto)+' ('+fmtPesos(valorNeto)+')',
        'Nombre: xxxxxxxxxxx'                                                                : 'Nombre: '+nombre,
        'Email: xxxxxxxxxxxxxx'                                                              : 'Email: '+correo,
        'Email: xxxxxxxxxxx'                                                                 : 'Email: '+correo,
        'Teléfono: xxxxxxx'                                                                  : 'Teléfono: '+celular,
        'Lugar: xxxxxxx'                                                                     : 'Lugar: '+lugar_exp,
        'Dirección: xxxxxxxx'                                                                : 'Dirección: '+direccion,
        'xx día del mes de xxxx'                                                             : dia+' día del mes de '+mes
      };
    }

    var resultBuffer = await replaceInDocx(docxBuffer, reps);
    var conNumFinal = 'CON-'+cotizNum+'-2026 '+nombre.toUpperCase();
    res.setHeader('Content-Type', 'application/vnd.openxmlformats-officedocument.wordprocessingml.document');
    res.setHeader('Content-Disposition', 'attachment; filename="'+conNumFinal+'.docx"');
    return res.send(resultBuffer);

  } catch (error) {
    console.error('[generar.js] ERROR:', error);
    return res.status(500).json({ error: error.message, stack: error.stack });
  }
};
